        def insert(val: int) -> None:
            node = 0
            for b in range(29, -1, -1):
                bit = (val >> b) & 1
                if bit == 0:
                    nxt = c0[node]
                    if nxt == -1:
                        nxt = len(c0)
                        c0[node] = nxt
                        c0.append(-1)
                        c1.append(-1)
                    node = nxt
                else:
                    nxt = c1[node]
