class Solution {
    public int binaryGap(int n) {
        int last = -1;
        int best = 0;
        int pos = 0;
        while (n > 0) {
            if ((n & 1) == 1) {
                if (last != -1 && pos - last > best) {
                    best = pos - last;
                }
                last = pos;
            }
            n >>>= 1;
            pos++;
        }
        return best;
    }
}

