class Solution {
    public int maxWordLengthProduct(String[] words) {
        Map<Integer, Integer> bestLen = new HashMap<>();
        for (String w : words) {
            int mask = 0;
            for (int i = 0; i < w.length(); i++) {
                mask |= 1 << (w.charAt(i) - 'a');
            }
            bestLen.merge(mask, w.length(), Math::max);
        }
        int m = bestLen.size();
        int[] masks = new int[m];
        int[] lens = new int[m];
        int idx = 0;
        for (Map.Entry<Integer, Integer> e : bestLen.entrySet()) {
            masks[idx] = e.getKey();
            lens[idx] = e.getValue();
            idx++;
        }
        int ans = 0;
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                if ((masks[i] & masks[j]) == 0) {
                    int prod = lens[i] * lens[j];
                    if (prod > ans) ans = prod;
                }
            }
        }
        return ans;
    }
}

solutionCode.python:
class Solution:
    def maxWordLengthProduct(self, words: List[str]) -> int:
        best_len = {}
        for w in words:
            mask = 0
            for ch in w:
                mask |= 1 << (ord(ch) - 97)
            if len(w) > best_len.get(mask, 0):
                best_len[mask] = len(w)
        items = list(best_len.items())
        ans = 0
        for i in range(len(items)):
            m1, l1 = items[i]
            for j in range(i + 1, len(items)):
                m2, l2 = items[j]
                if (m1 & m2) == 0 and l1 * l2 > ans:
                    ans = l1 * l2
        return ans

