                    if (same != 0) total += cnt[same];
                    node = (xb == 1) ? c0[node] : c1[node];
                } else {
                    node = (xb == 1) ? c1[node] : c0[node];
                }
                if (node == 0) break;
            }
            node = 0;
            for (int b = MAX_BIT; b >= 0; b--) {
                int xb = (x >> b) & 1;
                if (xb == 0) {
                    if (c0[node] == 0) c0[node] = nodes++;
                    node = c0[node];
                } else {
                    if (c1[node] == 0) c1[node] = nodes++;
                    node = c1[node];
                }
                cnt[node]++;
