    def countPairsXorInRange(self, nums: List[int], low: int, high: int) -> int:
        MAX_BIT = 15

        def count_less(limit: int) -> int:
            if limit <= 0:
                return 0
            c0 = [0]
            c1 = [0]
            cnt = [0]
            total = 0
            for x in nums:
                node = 0
                for b in range(MAX_BIT, -1, -1):
                    xb = (x >> b) & 1
                    lb = (limit >> b) & 1
                    if lb == 1:
                        same = c1[node] if xb == 1 else c0[node]
                        if same:
