                        nxt = c0[node] if xb == 1 else c1[node]
                    else:
                        nxt = c1[node] if xb == 1 else c0[node]
                    if nxt == 0:
                        break
                    node = nxt
                node = 0
                for b in range(MAX_BIT, -1, -1):
                    xb = (x >> b) & 1
                    if xb == 0:
                        if c0[node] == 0:
                            c0[node] = len(cnt)
                            c0.append(0)
                            c1.append(0)
