        MAX_B = 60
        comb = [[0] * (MAX_B + 1) for _ in range(MAX_B + 1)]
        for i in range(MAX_B + 1):
            comb[i][0] = 1
            for j in range(1, i + 1):
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j]
